1: use std::collections::VecDeque;
2: use tokio::sync::{Mutex, oneshot};
3: use tokio::task::JoinHandle;
4: 
5: #[derive(Default)]
6: pub struct Service {
7:     count: Mutex<u64>,
8: }
9: impl Service {
10:     pub async fn snapshot(&self) -> u64 {
11:         *self.count.lock().await
12:     }
13:     pub async fn increment_and_snapshot(&self) -> u64 {
14:         {
15:             let mut count = self.count.lock().await;
16:             *count += 1;
17:         }
18:         self.snapshot().await
19:     }
20: }
21: 
22: /// Dequeue only when approval arrives. Dropping this future must preserve the queue.
23: pub async fn approved_pop(
24:     queue: &Mutex<VecDeque<u64>>,
25:     approval: oneshot::Receiver<()>,
26: ) -> Option<u64> {
27:     approval.await.ok()?;
28:     queue.lock().await.pop_front()
29: }
30: 
31: /// Return only after the owned worker can no longer cause side effects.
32: pub async fn stop_worker(worker: JoinHandle<()>) {
33:     worker.abort();
34:     let _ = worker.await;
35: }
36: 
37: #[cfg(test)]
38: mod tests {
39:     use super::*;
40:     #[tokio::test]
41:     async fn snapshot_initial() {
42:         assert_eq!(Service::default().snapshot().await, 0);
43:     }
44:     #[tokio::test]
45:     async fn approved_delivery() {
46:         let queue = Mutex::new(VecDeque::from([7]));
47:         let (tx, rx) = oneshot::channel();
48:         tx.send(()).unwrap();
49:         assert_eq!(approved_pop(&queue, rx).await, Some(7));
50:     }
51: }

