1: /// C-ABI registration retains a read-only buffer until unregister returns.
2: pub struct Registration {
3:     bytes: *mut [u8],
4:     len: usize,
5:     unregister: unsafe extern "C" fn(),
6: }
7: impl Registration {
8:     /// Register a stable buffer with a foreign consumer.
9:     ///
10:     /// # Safety
11:     /// Callbacks must form one valid registration pair. register may retain and read
12:     /// the provided range but cannot write or free it. unregister must synchronously
13:     /// stop all reads before returning and must not unwind. Calls must be serialized
14:     /// by the owner; no other registration may replace the active one.
15:     pub unsafe fn new(
16:         bytes: Box<[u8]>,
17:         register: unsafe extern "C" fn(*const u8, usize),
18:         unregister: unsafe extern "C" fn(),
19:     ) -> Self {
20:         let len = bytes.len();
21:         let bytes = Box::into_raw(bytes);
22:         // SAFETY: allocation ownership stays with this raw-pointer owner. No Box
23:         // or reference is recreated until all foreign reads have stopped.
24:         unsafe { register(bytes.cast::<u8>(), len) };
25:         Self {
26:             bytes,
27:             len,
28:             unregister,
29:         }
30:     }
31:     pub fn len(&self) -> usize {
32:         self.len
33:     }
34:     pub fn is_empty(&self) -> bool {
35:         self.len == 0
36:     }
37: }
38: impl Drop for Registration {
39:     fn drop(&mut self) {
40:         // SAFETY: constructor contract guarantees synchronous quiescence.
41:         unsafe { (self.unregister)() };
42:         // SAFETY: this owns the original Box allocation; unregister stopped all
43:         // reads and no other owner frees it. Reconstruct exactly once.
44:         unsafe { drop(Box::from_raw(self.bytes)) };
45:     }
46: }

