1: /// Decode a native-endian word; short inputs return None, unaligned input is allowed.
2: pub fn read_word(bytes: &[u8]) -> Option<u32> {
3:     let raw: [u8; 4] = bytes.get(..4)?.try_into().ok()?;
4:     Some(u32::from_ne_bytes(raw))
5: }

