1: #[cfg(feature = "model")]
2: use loom::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
3: #[cfg(not(feature = "model"))]
4: use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
5: 
6: /// One-shot publication. The owner calls publish exactly once.
7: /// A reader observing Some must see the value passed to publish.
8: pub struct Published {
9:     value: AtomicUsize,
10:     ready: AtomicBool,
11: }
12: impl Default for Published {
13:     fn default() -> Self {
14:         Self {
15:             value: AtomicUsize::new(0),
16:             ready: AtomicBool::new(false),
17:         }
18:     }
19: }
20: impl Published {
21:     pub fn publish(&self, value: usize) {
22:         self.value.store(value, Ordering::Relaxed);
23:         self.ready.store(true, Ordering::Release);
24:     }
25:     pub fn snapshot(&self) -> Option<usize> {
26:         self.ready
27:             .load(Ordering::Acquire)
28:             .then(|| self.value.load(Ordering::Relaxed))
29:     }
30: }

