9: thread_local! { static RETAINED: Cell<*const u8> = const { Cell::new(std::ptr::null()) }; }
10: unsafe extern "C" fn retain(ptr: *const u8, _: usize) {
11:     RETAINED.with(|p| p.set(ptr));
12: }
13: unsafe extern "C" fn release() {
14:     RETAINED.with(|p| p.set(std::ptr::null()));
15: }
16: 
17: #[test]
18: fn ffi_storage_lives_until_unregister() {
19:     // SAFETY: these callbacks are serialized on the test thread, retain read-only
20:     // data, do not unwind, and release synchronously forgets the pointer.
21:     let registration = unsafe { Registration::new(vec![42].into_boxed_slice(), retain, release) };
22:     // SAFETY: the live registration is required to own the still-registered storage.
23:     let value = RETAINED.with(|p| unsafe { p.get().read() });
24:     assert_eq!(value, 42);
25:     drop(registration);
26:     assert!(RETAINED.with(|p| p.get().is_null()));
27: }

