1: #!/usr/bin/env bash
2: # Validate a standalone Markdown report from a file or stdin; no hook envelope.
3: set -euo pipefail
4: [[ $# -le 1 ]] || { echo 'Usage: check-report.sh [report.md]' >&2; exit 2; }
5: awk '
6: function error(message) { print message > "/dev/stderr"; bad=1 }
7: /^## / {
8:   section=$0
9:   if ($0 ~ /^## Verdict: (APPROVE|REQUEST_CHANGES|ESCALATE|INCOMPLETE)$/) {
10:     verdict=$3; verdict_count++
11:   }
12:   seen[$0]++
13: }
14: section == "## Gates" && /^- / {
15:   key=$2; sub(/:$/, "", key); value=$3
16:   if (key ~ /^(fmt|clippy|tests|doctests|deny)$/) {
17:     if (gate[key] != "") error("Duplicate gate: " key)
18:     gate[key]=value
19:     if (value == "NOT" && $4 == "RUN") gate[key]="NOT RUN"
20:     if (gate[key] !~ /^(PASS|FAIL|NOT RUN|N\/A)$/) error("Invalid gate status: " key)
21:     if (value == "N/A" && (key ~ /^(fmt|clippy|tests)$/ || NF < 4)) error("Invalid N/A: " key)
22:   }
23: }
24: section == "## Memory safety" && /^- / {
25:   key=$2; sub(/:$/, "", key)
26:   if (key ~ /^(memory-scope|miri|aliasing|memory-evidence|aliasing-evidence)$/) {
27:     if (memory_seen[key]++) error("Duplicate memory field: " key)
28:     memory[key]=$3
29:     if (key == "miri" && $3 == "NOT" && $4 == "RUN") memory[key]="NOT RUN"
30:     if (NF < 3) error("Empty memory field: " key)
31:   }
32: }
33: section == "## Concurrency" && /^- / {
34:   key=$2; sub(/:$/, "", key)
35:   if (key ~ /^(async-scope|deadlocks|cancellation|task-lifecycle|async-evidence|sync-scope|loom|synchronization|model-evidence)$/) {
36:     if (concurrency_seen[key]++) error("Duplicate concurrency field: " key)
37:     concurrency[key]=$3
38:     if ($3 == "NOT" && $4 == "RUN") concurrency[key]="NOT RUN"
39:     concurrency_words[key]=NF
40:     if (NF < 3) error("Empty concurrency field: " key)
41:   }
42: }
43: section == "## Spec" && /^- spec:/ {
44:   spec_count++; spec=$3
45:   if (spec == "NOT" && $4 == "RUN") spec="NOT RUN"
46:   if (spec !~ /^(PASS|FAIL|PARTIAL|NOT RUN)$/) error("Invalid spec status")
47: }
48: section == "## Spec" && /^- (missing|unrequested|contradictions): .+/ { spec_fields[$2]++ }
49: section == "## Findings" && /^- \[P[0-3]\] / {
50:   findings++
51:   if ($0 !~ /[^ ]+:[1-9][0-9]* - .+/) error("Finding missing file:line or explanation")
52:   if ($2 ~ /\[P[01]\]/) blocking=1
53: }
54: section == "## Findings" && /^No findings\.$/ { empty_findings++ }
55: END {
56:   if (verdict_count != 1) error("Exactly one valid Verdict required")
57:   required[1]="## Gates"; required[2]="## Spec"; required[3]="## Findings"; required[4]="## Residual risks"; required[5]="## Memory safety"
58:   required[6]="## Concurrency"
59:   for (i=1;i<=6;i++) if (seen[required[i]] != 1) error("Missing/duplicate section: " required[i])
60:   split("fmt clippy tests doctests deny", names, " ")
61:   for (i=1;i<=5;i++) {
62:     key=names[i]
63:     if (gate[key] == "") error("Missing gate: " key)
64:     if (verdict == "APPROVE" && gate[key] != "PASS" && gate[key] != "N/A") error("APPROVE requires completed gates: " key)
65:   }
66:   if (spec_count != 1) error("Exactly one spec status required")
67:   split("missing: unrequested: contradictions:", names, " ")
68:   for (i=1;i<=3;i++) if (spec_fields[names[i]] != 1) error("Missing/duplicate spec field: " names[i])
69:   if ((!findings && empty_findings != 1) || (findings && empty_findings)) error("Provide findings or No findings., not both")
70:   if (verdict == "APPROVE" && (spec != "PASS" || blocking)) error("APPROVE conflicts with spec or P0/P1 findings")
71:   split("memory-scope miri aliasing memory-evidence aliasing-evidence", names, " ")
72:   for (i=1;i<=5;i++) if (memory_seen[names[i]] != 1) error("Missing memory field: " names[i])
73:   if (memory["memory-scope"] !~ /^(REQUIRED|NONE)$/) error("Invalid memory scope")
74:   if (memory["miri"] !~ /^(PASS|FAIL|NOT RUN|N\/A)$/) error("Invalid Miri status")
75:   if (memory["aliasing"] !~ /^(PASS|FAIL|UNRESOLVED|N\/A)$/) error("Invalid aliasing status")
76:   if (memory["memory-scope"] == "NONE") {
77:     if (memory["miri"] != "N/A" || memory["aliasing"] != "N/A") error("NONE scope requires N/A memory checks")
78:   } else if (memory["memory-scope"] == "REQUIRED") {
79:     if (memory["miri"] == "N/A" || memory["aliasing"] == "N/A") error("Required memory checks cannot be N/A")
80:     if (memory["memory-evidence"] == "N/A" || memory["aliasing-evidence"] == "N/A") error("Required memory assessment needs evidence or explicit gaps")
81:     if ((memory["miri"] == "NOT RUN" || memory["aliasing"] == "UNRESOLVED") && verdict != "ESCALATE") error("Unresolved memory obligations require ESCALATE")
82:     if (verdict == "APPROVE" && (memory["miri"] != "PASS" || memory["aliasing"] != "PASS")) error("APPROVE requires targeted Miri and aliasing PASS")
83:     if ((memory["miri"] == "FAIL" || memory["aliasing"] == "FAIL") && verdict !~ /^(REQUEST_CHANGES|ESCALATE)$/) error("Memory failure blocks approval/completion")
84:   }
85:   split("async-scope deadlocks cancellation task-lifecycle async-evidence sync-scope loom synchronization model-evidence", names, " ")
86:   for (i=1;i<=9;i++) if (concurrency_seen[names[i]] != 1) error("Missing concurrency field: " names[i])
87:   if (concurrency["async-scope"] !~ /^(REQUIRED|NONE)$/) error("Invalid async scope")
88:   if (concurrency["sync-scope"] !~ /^(REQUIRED|NONE)$/) error("Invalid synchronization scope")
89:   split("deadlocks cancellation task-lifecycle", names, " ")
90:   applicable=0
91:   for (i=1;i<=3;i++) {
92:     key=names[i]; value=concurrency[key]
93:     if (value !~ /^(PASS|FAIL|NOT RUN|N\/A)$/) error("Invalid async status: " key)
94:     if (value == "N/A" && concurrency_words[key] < 4) error("N/A needs an applicability reason: " key)
95:     if (concurrency["async-scope"] == "NONE" && value != "N/A") error("NONE async scope requires N/A: " key)
96:     if (concurrency["async-scope"] == "REQUIRED") {
97:       if (value != "N/A") applicable++
98:       if (value == "NOT RUN" && verdict != "ESCALATE") error("Missing targeted async evidence requires ESCALATE: " key)
99:       if (value == "FAIL" && verdict !~ /^(REQUEST_CHANGES|ESCALATE)$/) error("Async failure blocks approval/completion: " key)
100:     }
101:   }
102:   if (concurrency["async-scope"] == "REQUIRED") {
103:     if (!applicable) error("Required async scope cannot mark all checks N/A")
104:     if (concurrency["async-evidence"] == "N/A") error("Required async assessment needs evidence or explicit gaps")
105:   }
106:   if (concurrency["loom"] !~ /^(PASS|FAIL|NOT RUN|N\/A)$/) error("Invalid Loom status")
107:   if (concurrency["synchronization"] !~ /^(PASS|FAIL|UNRESOLVED|N\/A)$/) error("Invalid synchronization status")
108:   if (concurrency["sync-scope"] == "NONE") {
109:     if (concurrency["loom"] != "N/A" || concurrency["synchronization"] != "N/A") error("NONE sync scope requires N/A checks")
110:   } else if (concurrency["sync-scope"] == "REQUIRED") {
111:     if (concurrency["loom"] == "N/A" || concurrency["synchronization"] == "N/A") error("Required synchronization checks cannot be N/A")
112:     if (concurrency["model-evidence"] == "N/A") error("Required synchronization assessment needs model evidence or explicit gaps")
113:     if ((concurrency["loom"] == "NOT RUN" || concurrency["synchronization"] == "UNRESOLVED") && verdict != "ESCALATE") error("Incomplete synchronization evidence requires ESCALATE")
114:     if ((concurrency["loom"] == "FAIL" || concurrency["synchronization"] == "FAIL") && verdict !~ /^(REQUEST_CHANGES|ESCALATE)$/) error("Synchronization failure blocks approval/completion")
115:   }
116:   exit bad ? 1 : 0
117: }' "${1:--}"

